package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.IntNode;
import com.fasterxml.jackson.databind.node.NumericNode;
import com.fasterxml.jackson.databind.node.TextNode;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TreeTraversingParser#getIntValue
 */
public class TreeTraversingParser_getIntValue_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    /**
     * Test successful retrieval of an integer value from a NumericNode.
     */
    @Test
    public void testGetIntValue_Success() throws IOException {
        // Arrange
        IntNode intNode = mapper.getNodeFactory().numberNode(42);
        TreeTraversingParser parser = new TreeTraversingParser(intNode, mapper);

        // Act
        int result = parser.getIntValue();

        // Assert
        Assert.assertEquals(42, result);
    }

    /**
     * Test successful retrieval of a long value cast to int.
     */
    @Test
    public void testGetIntValue_LongValue() throws IOException {
        // Arrange
        // Using a value that fits in int but is technically a LongNode
        IntNode longNode = mapper.getNodeFactory().numberNode(1000);
        TreeTraversingParser parser = new TreeTraversingParser(longNode, mapper);

        // Act
        int result = parser.getIntValue();

        // Assert
        Assert.assertEquals(1000, result);
    }

    /**
     * Test that calling getIntValue when the current node is not a NumericNode 
     * throws a ClassCastException (as per the implementation casting to NumericNode).
     */
    @Test(expected = ClassCastException.class)
    public void testGetIntValue_NotNumericNode_ThrowsException() throws IOException {
        // Arrange
        TextNode textNode = mapper.getNodeFactory().textNode("not a number");
        TreeTraversingParser parser = new TreeTraversingParser(textNode, mapper);

        // Act
        parser.getIntValue();
    }

    /**
     * Test that calling getIntValue when the current node is null 
     * throws a NullPointerException.
     */
    @Test(expected = NullPointerException.class)
    public void testGetIntValue_NullNode_ThrowsException() throws IOException {
        // Arrange
        // We simulate this by passing a node that might lead to a null currentNumericNode
        // However, since TreeTraversingParser is initialized with a node, 
        // we use a mock to force currentNumericNode to return null.
        TreeTraversingParser parser = mock(TreeTraversingParser.class);
        when(parser.getIntValue()).thenAnswer(invocation -> {
            // This mimics the internal logic of the real method to trigger NPE
            // because the real method does (NumericNode) currentNumericNode()
            // if currentNumericNode returns null, casting works but accessing .intValue() fails.
            return ((NumericNode) null).intValue();
        });

        // Act
        parser.getIntValue();
    }

    /**
     * Test that the method propagates IOException if the underlying parser fails.
     */
    @Test(expected = IOException.class)
    public void testGetIntValue_ThrowsIOException() throws IOException {
        // Arrange
        TreeTraversingParser parser = mock(TreeTraversingParser.class);
        when(parser.getIntValue()).thenThrow(new IOException("Simulated IO failure"));

        // Act
        parser.getIntValue();
    }
}
